# Review package: 8bab44a01cfd159dcc5a5d0dbe55715ee785d541..HEAD

## Commits
7606160 Add greeting function with custom formatting

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 35 +++++++++++++++++++++++++++++++++++
 2 files changed, 43 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..c56228a
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name) {
+    return 'Hello, guest! Welcome!';
+  }
+  return `Hello, ${name}! Welcome!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..4e1ae05
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,35 @@
+const { describe, it } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet.js');
+
+describe('greet', () => {
+  it('returns a formatted greeting for a normal name', () => {
+    const result = greet('Alice');
+    assert.strictEqual(result, 'Hello, Alice! Welcome!');
+  });
+
+  it('returns a formatted greeting for another name', () => {
+    const result = greet('Bob');
+    assert.strictEqual(result, 'Hello, Bob! Welcome!');
+  });
+
+  it('handles empty string gracefully', () => {
+    const result = greet('');
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles null input gracefully', () => {
+    const result = greet(null);
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles undefined input gracefully', () => {
+    const result = greet(undefined);
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles no argument gracefully', () => {
+    const result = greet();
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+});
